// Webhook'tan gelen isteğe göre görev listesini günceller.
// Desteklenen işlemler: ekle (varsayılan), tamamla, sil.
const okunan = $input.first().json;
const mevcut = (okunan.data && okunan.data.gorevler) || okunan.gorevler || [];
const gorevler = Array.isArray(mevcut) ? [...mevcut] : [];

const govde = $('Görev Webhook (POST)').first().json.body || {};
const islem = String(govde.islem || 'ekle').toLowerCase();
let mesaj = '';

if (islem === 'ekle') {
  const baslik = String(govde.baslik || '').trim();
  if (!baslik) {
    mesaj = 'HATA: "baslik" alanı zorunlu.';
  } else {
    const yeniId = gorevler.reduce((m, g) => Math.max(m, Number(g.id) || 0), 0) + 1;
    gorevler.push({
      id: yeniId,
      baslik,
      not: String(govde.not || ''),
      durum: 'acik',
      olusturulma: new Date().toISOString(),
    });
    mesaj = `Görev eklendi (#${yeniId}): ${baslik}`;
  }
} else if (islem === 'tamamla' || islem === 'sil') {
  const id = Number(govde.id);
  const gorev = gorevler.find((g) => Number(g.id) === id);
  if (!gorev) {
    mesaj = `HATA: #${id} numaralı görev bulunamadı.`;
  } else if (islem === 'tamamla') {
    gorev.durum = 'tamam';
    gorev.tamamlanma = new Date().toISOString();
    mesaj = `Görev tamamlandı (#${id}): ${gorev.baslik}`;
  } else {
    gorevler.splice(gorevler.indexOf(gorev), 1);
    mesaj = `Görev silindi (#${id}): ${gorev.baslik}`;
  }
} else {
  mesaj = `HATA: bilinmeyen işlem "${islem}". Geçerli işlemler: ekle, tamamla, sil.`;
}

const acikGorevSayisi = gorevler.filter((g) => g.durum !== 'tamam').length;
return [{ json: { gorevler, mesaj, acikGorevSayisi } }];

// Açık görevlerden Türkçe bir HTML hatırlatma maili hazırlar.
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));

const okunan = $input.first().json;
const ham = (okunan.data && okunan.data.gorevler) || okunan.gorevler || [];
const acik = (Array.isArray(ham) ? ham : []).filter((g) => g && g.durum !== 'tamam');

const bugun = new Date().toLocaleDateString('tr-TR', {
  weekday: 'long', day: 'numeric', month: 'long',
});

let html;
if (acik.length === 0) {
  html = '<div style="font-family:sans-serif"><h2>✅ Görevler</h2><p>Bugün için açık görev yok. 🎉</p></div>';
} else {
  const satirlar = acik
    .map((g) => `<li style="margin:4px 0"><b>#${g.id}</b> ${esc(g.baslik)}${g.not ? ` — <span style="color:#555">${esc(g.not)}</span>` : ''}</li>`)
    .join('');
  html = [
    '<div style="font-family:sans-serif;max-width:640px">',
    `<h2>✅ Bugünün görevleri — ${bugun}</h2>`,
    `<ol style="padding-left:20px">${satirlar}</ol>`,
    '<p style="color:#999;font-size:12px">Tamamlamak için: POST http://localhost:5678/webhook/gorev gövde: {"islem":"tamamla","id":1}</p>',
    '</div>',
  ].join('');
}

return [{ json: { konu: `[n8n] ✅ Bugünün görevleri (${acik.length} açık) — ${bugun}`, html } }];
